mapper.select:
SELECT id, name, code, category, price, unit, description, enable, sort,
       organization_id, create_user, update_user, create_time, update_time
FROM product
WHERE code = #{code}
  AND organization_id = #{organizationId}

SELECT id, name, code, category, price, unit, description, enable, sort,
       organization_id, create_user, update_user, create_time, update_time
FROM product
WHERE organization_id = #{organizationId}

    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR code LIKE CONCAT('%', #{keyword}, '%'))


    AND category = #{category}


    AND enable = #{enable}

ORDER BY sort ASC, create_time DESC
